-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/silver/silver_observation.sql. Do not edit.
-- Silver observation: one row per result, with a LOINC code where one is known
-- (at the source, or through the curated MIMIC lab seed).
CREATE OR REPLACE TABLE silver_observation AS
WITH latest AS (
    SELECT *
    FROM bronze_resources
    WHERE resource_type = 'Observation'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
),
typed AS (
    SELECT
        resource_id                                                AS observation_id,
        REPLACE(raw:subject.reference::string, 'Patient/', '')       AS patient_id,
        REPLACE(raw:encounter.reference::string, 'Encounter/', '')   AS encounter_id,
        raw:category[0].coding[0].code::string                       AS category,
        raw:status::string                                           AS status,
        raw:code.coding[0].system::string                            AS code_system,
        raw:code.coding[0].code::string                              AS code,
        COALESCE(raw:code.text::string, raw:code.coding[0].display::string) AS description,
        TRY_CAST(raw:valueQuantity.value::string AS DOUBLE)                           AS value_num,
        raw:valueQuantity.comparator::string                         AS comparator,
        COALESCE(raw:valueQuantity.unit::string, raw:valueQuantity.code::string) AS unit,
        raw:valueString::string                                      AS value_text,
        TRY_CAST(raw:referenceRange[0].low.value::string AS DOUBLE)                   AS ref_low,
        TRY_CAST(raw:referenceRange[0].high.value::string AS DOUBLE)                  AS ref_high,
        raw:interpretation[0].coding[0].code::string                 AS interpretation,
        COALESCE(TRY_CAST(SUBSTR(raw:effectiveDateTime::string, 1, 19) AS TIMESTAMP_NTZ), TRY_CAST(SUBSTR(raw:effectivePeriod.start::string, 1, 19) AS TIMESTAMP_NTZ), TRY_CAST(SUBSTR(raw:issued::string, 1, 19) AS TIMESTAMP_NTZ)) AS effective_at,
        source_file,
        loaded_at
    FROM latest
)
SELECT
    t.observation_id,
    t.patient_id,
    t.encounter_id,
    t.category,
    t.status,
    t.code_system,
    t.code,
    t.description,
    CASE
        WHEN t.code_system = 'http://loinc.org' THEN t.code
        WHEN t.code_system = 'http://mimic.mit.edu/fhir/mimic/CodeSystem/mimic-d-labitems' THEN m.loinc
    END                                                            AS loinc,
    t.value_num,
    t.comparator,
    t.unit,
    t.value_text,
    t.ref_low,
    t.ref_high,
    CASE
        WHEN t.value_num IS NULL OR t.comparator IS NOT NULL THEN NULL
        WHEN t.ref_high IS NOT NULL AND t.value_num > t.ref_high THEN 'high'
        WHEN t.ref_low IS NOT NULL AND t.value_num < t.ref_low THEN 'low'
        WHEN t.ref_low IS NOT NULL OR t.ref_high IS NOT NULL THEN 'normal'
    END                                                            AS range_flag,
    t.interpretation,
    t.effective_at,
    t.source_file,
    t.loaded_at
FROM typed t
LEFT JOIN seed_lab_loinc m
    ON t.code_system = 'http://mimic.mit.edu/fhir/mimic/CodeSystem/mimic-d-labitems'
   AND m.mimic_code = t.code;
